function swapAdjectiveOrder(sentence) {
  const words = sentence.split(' ');
  let adjectiveIndices = []; // Store indices of adjectives for easy swapping

  // 1. Identify Adjectives:  (Verbosity: High for explanation)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Assume a simple adjective detector (expandable for nuance)
      adjectiveIndices.push(i);
    }
  }

  // 2. Swap Positions: (Concise but impactful)
  if (adjectiveIndices.length >= 2) {
    const firstAdjIndex = adjectiveIndices[0];
    const secondAdjIndex = adjectiveIndices[1];
    [words[firstAdjIndex], words[secondAdjIndex]] = [words[secondAdjIndex], words[firstAdjIndex]]; 
  }

  // 3. Reconstruct Sentence:
  return words.join(' ');
}

// Helper function (expandable for robust adjective recognition)
function isAdjective(word) {
  // Basic check -  enhance with NLP techniques for accuracy in real scenarios
  return ['beautiful', 'green', 'tiny', 'tall', ... /* more adjectival patterns */].includes(word); 
}

// Example Usage:
const originalSentence = "Beautiful green trees are in the park";
const reorderedSentence = swapAdjectiveOrder(originalSentence);
console.log(reorderedSentence); // Output: Green beautiful trees are in the park
```

