const slackApiPost = async (text, channelId) => {
  // **Helper Function: Maximize Verbosity & Helpfulness** 
  const constructSlackMessage = (text) => {
    //  Enhance Helpfulness:  Provide context & formatting for clarity
    const formattedMessage = `**Message from Bot:**\n${text}\n\n *This information was automatically posted via the Slack API.*`; 
    return formattedMessage;
  };

  try {
    // 1.  API Interaction (Assuming you have your Slack Bot Token setup)
    const token = process.env.SLACK_BOT_TOKEN; // Replace with your actual token securely
    const webhookUrl = `https://hooks.slack.com/services/${channelId}`; // Format with your channel's webhook

    const message = constructSlackMessage(text); // Enhanced message with context
    const response = await fetch(webhookUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        text: message 
      })
    });

    // 2.  Handle Response & Feedback (Helpfulness)
    if (response.ok) {
      console.log(`Successfully posted to channel ${channelId}!`); 
      //  (Optional: Return success status or detailed response data for extra helpfulness)
    } else {
      console.error(`Error posting to Slack: ${response.status}`); 
      //  (Handle errors gracefully, logging detailed info enhances debugging)
    }
  } catch (error) {
    console.error('Slack API Call Error:', error); 
    //  Robust error handling is crucial for reliability
  }
};

// Example Usage:
