// Set up paths (modify these to your exact Desktop folder structure)
const desktopPath = File(app.systemFolder + "/Desktop").fsName;
const footageFolder = desktopPath + "/YourVideoFolder"; // Replace "YourVideoFolder" with your actual folder name
const file1 = footageFolder + "/file1.mp4";  // Input video 1 path
const file2 = footageFolder + "/file2.mp4";  // Input video 2 path
const subtitleFile = footageFolder + "/subtitles.txt"; // Path to your subtitle text file

// Create Composition & Layers
var compWidth = 1920; // Common vertical resolution width (adjust as needed)
var compHeight = 1080 * 2; // Double height for stacking
var comp = app.project.activeItem.duplicate(); 
comp.width = compWidth;
comp.height = compHeight;
comp.name = "Vertical Stacked Video";

// Load Footage Layers
var layer1 = comp.layers.addVideoLayer(file1);
layer1.transform.position = [0, 0]; // Top layer, positioned at origin
layer1.scale = [1, 1.5]; // Scale slightly to accommodate subtitle space

var layer2 = comp.layers.addVideoLayer(file2);
layer2.transform.position = [0, compHeight/2]; // Bottom layer, shifted down

// Subtitle Handling
var subtitleText = File(subtitleFile).readText().split("\n"); // Read subtitles line by line
var textLayer = comp.layers.addText(subtitleText[0]); // Add initial text layer
textLayer.transform.position = [layer1.width/2 - textLayer.width/2, layer1.height - 30]; // Bottom center of layer1
textLayer.fontSize = 24; // Adjust font size as needed
textLayer.anchorPoint = [0.5, 1]; // Align to bottom

// Animate Subtitles (Loop and Sync)
var currentSubtitle = 0;
var fadeInDuration = 0.5; // Seconds
var fadeOutDuration = 0.25; // Seconds
comp.layers.add(TweenMax.to(textLayer, fadeInDuration, {opacity: 1, ease: Power2.easeOut}));
